mapper.select:
SELECT B.ChnlCode, B.BoardNo, B.BoardTitle, B.BoardCntnts, B.EventCode, E.EventName, B.CustId, B.CustName, B.State, B.Remark, B.RegistId, B.RegistName, B.RegistDate, B.ChangeId, B.ChangeName, B.ChangeDate FROM shopion.tStrEventBoard B INNER JOIN shopion.tStrEvent E ON B.ChnlCode = E.ChnlCode AND B.EventCode = E.EventCode
AND B.ChnlCode = #{pChnlCode}
AND B.EventCode = #{pEventCode}
ORDER BY B.BoardNo DESC

SELECT B.ChnlCode, B.BoardNo, B.BoardTitle, B.BoardCntnts, B.EventCode, E.EventName,
       B.CustId, B.CustName, B.State, B.Remark,
       B.RegistId, B.RegistName, B.RegistDate, B.ChangeId, B.ChangeName, B.ChangeDate
FROM shopion.tStrEventBoard B
INNER JOIN shopion.tStrEvent E ON B.ChnlCode = E.ChnlCode AND B.EventCode = E.EventCode


        AND B.ChnlCode = #{pChnlCode}


        AND B.EventCode = #{pEventCode}


ORDER BY B.BoardNo DESC
LIMIT #{startNum}, #{countPerPage}

SELECT COUNT(*)
FROM shopion.tStrEventBoard B
INNER JOIN shopion.tStrEvent E ON B.ChnlCode = E.ChnlCode AND B.EventCode = E.EventCode


        AND B.ChnlCode = #{pChnlCode}


        AND B.EventCode = #{pEventCode}

mapper.insert:
INSERT INTO shopion.tStrEventBoard (
    ChnlCode, BoardTitle, BoardCntnts, EventCode, CustId, CustName,
    State, Remark, RegistId, RegistName, RegistDate, ChangeId, ChangeName, ChangeDate
) VALUES (
    #{chnlCode}, #{boardTitle}, #{boardCntnts}, #{eventCode}, #{custId}, #{custName},
    #{state}, #{remark}, #{registId}, #{registName}, #{registDate}, #{changeId}, #{changeName}, #{changeDate}
)

mapper.delete:
DELETE FROM shopion.tStrEventBoard
WHERE ChnlCode = #{pChnlCode}
  AND BoardNo = #{pBoardNo}

DELETE FROM shopion.tStrEventBoard
WHERE ChnlCode = #{pChnlCode}
  AND EventCode = #{pEventCode}
